def remove(node):
    node.prev.next = node.next
    node.next.prev = node.prev

def has_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            return True
    return False

def valid(s):
    pairs, st = {')': '(', ']': '[', '}': '{'}, []
    for c in s:
        if c in pairs:
            if not st or st.pop() != pairs[c]: return False
        else:
            st.append(c)
    return not st

